    paths.root=Join(Join(paths.local,L"Programs"),L"Explorer MVP");paths.links=Join(programs,L"Explorer MVP");paths.legacy=Join(Join(Join(paths.local,L"Programs"),L"Win10NativePatch"),L"NativeSnap.exe");return true;
