    EmbeddedFile first{L"LICENSE.txt",one,sizeof(one),{}},second{L"README.txt",two,sizeof(two),{}};
    Hash(one,sizeof(one),nullptr,first.sha256);Hash(two,sizeof(two),nullptr,second.sha256);
